ALIGNED_POST_CSS = '''<style data-cognis-aligned-post>
html,body{height:auto}.post-hero{max-width:820px;margin:0 auto;padding:150px 24px 0}.post-hero .ph-kicker{display:flex;align-items:center;gap:10px;font-family:Geistmono,ui-monospace,monospace;font-size:13px;letter-spacing:.12em;text-transform:uppercase;color:#7b7b7b;margin:0 0 22px}.post-hero .ph-kicker:before{content:"";width:8px;height:8px;background:#131313;flex:none}.post-hero h1{font-family:"Plus Jakarta Sans",sans-serif;font-weight:600;letter-spacing:-.03em;font-size:clamp(34px,4.6vw,54px);line-height:1.08;margin:0;color:#131313}.post-hero-img{max-width:1080px;margin:44px auto 0;padding:0 24px}.post-hero-img figure{margin:0;position:relative}.post-hero-img img{width:100%;height:auto;max-height:540px;aspect-ratio:2/1;object-fit:cover;border-radius:24px;display:block}.post-hero-img figcaption{position:absolute;right:14px;bottom:12px;background:rgba(0,0,0,.72);color:#fff;padding:6px 9px;border-radius:7px;font:11px/1.3 Inter,sans-serif}article.cognis-longform{max-width:760px;margin:40px auto 96px;padding:0 24px;font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;color:#131313;font-size:17px;line-height:1.72}article.cognis-longform .lf-lead{font-size:20px;line-height:1.55;color:#2f2f2f;margin:0 0 24px;font-weight:500}article.cognis-longform .lf-byline{color:#7b7b7b;font-size:14px;margin:0 0 40px;padding-bottom:24px;border-bottom:1px solid #e6e6e6}article.cognis-longform .lf-byline a{color:#131313;text-decoration:none;font-weight:600}article.cognis-longform h2{font-size:26px;line-height:1.25;letter-spacing:-.01em;margin:40px 0 14px;font-weight:700}article.cognis-longform h3{font-size:20px;line-height:1.3;margin:32px 0 12px}article.cognis-longform p{margin:0 0 16px}article.cognis-longform ul,article.cognis-longform ol{padding-left:22px;margin:0 0 18px}article.cognis-longform li{margin-bottom:8px}article.cognis-longform a{color:#131313;text-decoration:underline;text-underline-offset:3px}article.cognis-longform a:hover{background:#cdfb56}article.cognis-longform .lf-related{margin-top:40px;padding:28px;background:#fff;border:1px solid #e6e6e6;border-radius:12px}article.cognis-longform .lf-related h2{margin:0 0 12px;font-size:18px}article.cognis-longform .lf-related p,article.cognis-longform .lf-related li{font-size:15px;line-height:1.6}@media(max-width:767px){html,body{overflow-x:hidden}.post-hero{padding-top:112px}.post-hero-img{padding:0 16px;margin-top:28px}.post-hero-img img{border-radius:16px;aspect-ratio:3/2}article.cognis-longform{padding:0 20px}[data-dc-tpl="14"]{display:none!important}[data-dc-tpl="8"]{padding:18px 16px!important}[data-dc-tpl="35"]{font-size:11px!important;padding:10px 14px!important}[data-dc-tpl="86"]{grid-template-columns:1fr!important;gap:28px!important}[data-dc-tpl="111"]{flex-wrap:wrap!important}[data-dc-tpl="116"]{min-width:0;width:100%}[data-dc-tpl="119"]{align-items:flex-start!important;flex-direction:column!important;gap:16px!important}}
</style>'''

def aligned_post_page(page, p):
    reference=(ROOT/'blog/building-ai-agents-that-actually-ship/index.html').read_text()
    native_style=re.search(r'<style data-dc-tpl="5">[\s\S]*?</style>',reference).group(0)
    native_header=re.search(r'<div data-dc-tpl="7"[\s\S]*?(?=\s*<main id="content">)',reference).group(0)
    native_footer=re.search(r'<footer data-dc-tpl="84"[\s\S]*?</footer>',reference).group(0)
    related=''.join(f'<li><a href="{u}">{html.escape(t)} →</a></li>' for t,u in p['related'])
    body=f'''<body><div style="background: rgb(242, 242, 242); position: relative; min-height: 100vh;">{native_header}<main id="content"><div class="post-hero"><p class="ph-kicker">Insights · July 26, 2026</p><h1>{html.escape(p['title'])}</h1></div><div class="post-hero-img"><figure><img src="/assets/blog/{p['image']}" width="1600" height="900" fetchpriority="high" alt="{html.escape(p['alt'])}"><figcaption>Photo: <a href="{p['source']}">{html.escape(p['credit'])} / Unsplash</a></figcaption></figure></div><article class="cognis-longform" data-cognis-slug="{p['slug']}"><p class="lf-lead">{html.escape(p['lead'])}</p><p class="lf-byline">By <a rel="author" href="/teams/{p['author_slug']}/">{html.escape(p['author'])}</a> · {html.escape(p['role'])} · {p['reading']}</p>{p['body']}<aside class="lf-related"><h2>Method and sources</h2><p>This practitioner analysis was reviewed on 26 July 2026. It separates cited external requirements and guidance from Cognis Group’s implementation recommendations. Links throughout point to the primary standards and engineering guidance reviewed.</p></aside><aside class="lf-related"><h2>Continue reading</h2><ul>{related}</ul></aside></article></main>{native_footer}</div><script src="/cognis.js" defer></script></body>'''
    page=re.sub(r'<body>[\s\S]*?</body>',body,page,count=1)
    return page.replace('</head>',native_style+ALIGNED_POST_CSS+'</head>',1)

def schema(p):
    url=f'https://cognis.group/blog/{p["slug"]}/'; pid=f'https://cognis.group/teams/{p["author_slug"]}/#person'; image=f'https://cognis.group/assets/blog/{p["image"]}'
    return {"@context":"https://schema.org","@graph":[{"@type":"WebPage","@id":url+"#webpage","url":url,"name":p["title"],"datePublished":DATE,"dateModified":DATE,"breadcrumb":{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://cognis.group/"},{"@type":"ListItem","position":2,"name":"Insights","item":"https://cognis.group/blog/"},{"@type":"ListItem","position":3,"name":p["title"],"item":url}]}},{"@type":"BlogPosting","@id":url+"#article","mainEntityOfPage":{"@id":url+"#webpage"},"headline":p["title"],"description":p["dek"],"datePublished":DATE,"dateModified":DATE,"image":image,"inLanguage":"en-GB","articleSection":p["topic"],"author":{"@id":pid},"publisher":{"@id":"https://cognis.group/#organization"}},{"@type":"Person","@id":pid,"name":p["author"],"jobTitle":p["role"],"url":f'https://cognis.group/teams/{p["author_slug"]}/',"worksFor":{"@id":"https://cognis.group/#organization"}},{"@type":"Organization","@id":"https://cognis.group/#organization","name":"Cognis Group","url":"https://cognis.group/","logo":{"@type":"ImageObject","url":"https://cognis.group/assets/img/cognis-logo.png"}}]}

def render(p):
    url=f'https://cognis.group/blog/{p["slug"]}/'; image=f'https://cognis.group/assets/blog/{p["image"]}'; related=''.join(f'<li><a href="{u}">{html.escape(t)}</a></li>' for t,u in p['related'])
    return f'''<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(p['title'])} | Cognis Group</title><meta name="description" content="{html.escape(p['dek'])}"><link rel="canonical" href="{url}"><link rel="alternate" hreflang="en" href="{url}"><link rel="alternate" hreflang="x-default" href="{url}"><meta property="og:type" content="article"><meta property="og:title" content="{html.escape(p['title'])}"><meta property="og:description" content="{html.escape(p['dek'])}"><meta property="og:url" content="{url}"><meta property="og:image" content="{image}"><meta property="article:published_time" content="{DATE}"><meta property="article:modified_time" content="{DATE}"><meta property="article:author" content="https://cognis.group/teams/{p['author_slug']}/"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{html.escape(p['title'])}"><meta name="twitter:description" content="{html.escape(p['dek'])}"><meta name="twitter:image" content="{image}"><link rel="icon" href="/favicon.svg"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&amp;family=Plus+Jakarta+Sans:wght@400;500;600;700;800&amp;display=swap" rel="stylesheet"><style>{CSS}</style><script type="application/ld+json">{json.dumps(schema(p),ensure_ascii=False)}</script></head><body><header class="head"><a class="brand" href="/"><img src="/favicon.svg" alt="">Cognis</a><nav class="nav"><a href="/about-us/">About</a><a href="/our-services/">Services</a><a href="/products/">Products</a><a href="/blog/">Insights</a></nav><a class="cta" href="/contact/">Work with us</a></header><main><header class="hero"><div class="hero-copy"><div class="kicker">{html.escape(p['topic'])} · Expert field note</div><h1>{html.escape(p['title'])}</h1><p class="dek">{html.escape(p['dek'])}</p><div class="byline"><span>By <a rel="author" href="/teams/{p['author_slug']}/">{html.escape(p['author'])}</a>, {html.escape(p['role'])}</span><span>•</span><time datetime="{DATE}">26 July 2026</time><span>•</span><span>{p['reading']}</span></div></div><figure><img src="/assets/blog/{p['image']}" width="1600" height="900" fetchpriority="high" alt="{html.escape(p['alt'])}"><figcaption>Photo: <a href="{p['source']}">{html.escape(p['credit'])} / Unsplash</a></figcaption></figure></header><article class="article"><p class="lead">{html.escape(p['lead'])}</p>{p['body']}<section class="box"><h2>Method and sources</h2><p>This practitioner analysis was reviewed on 26 July 2026. It separates cited external requirements and guidance from Cognis Group’s implementation recommendations. Links throughout point to the primary standards and engineering guidance reviewed.</p></section><section class="box"><h2>Continue reading</h2><ul>{related}</ul></section></article></main><footer class="foot"><a class="brand" href="/"><img src="/favicon.svg" alt="">Cognis</a><p>Cognis Group builds, deploys, and governs AI systems that permanently transform organisations.</p><nav class="links"><a href="/our-services/">Services</a><a href="/case-studies/">Case studies</a><a href="/blog/">Insights</a><a href="/contact/">Contact</a></nav></footer></body></html>'''

def update_hub():
    path=ROOT/'blog/index.html'; text=path.read_text(); text=re.sub(r'<!-- expert-posts:start -->.*?<!-- expert-posts:end -->','',text,flags=re.S)
    text=re.sub(r'<!-- expert-cards:start -->.*?<!-- expert-cards:end -->','',text,flags=re.S)
    arrow='<span data-dc-tpl="68" style="position: absolute; right: 16px; bottom: 16px; width: 48px; height: 48px; border-radius: 50%; background: rgb(255, 255, 255); display: flex; align-items: center; justify-content: center; box-shadow: rgba(0, 0, 0, 0.18) 0px 6px 16px;"><svg data-dc-tpl="69" xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 20 20" fill="none"><path data-dc-tpl="70" d="M13.0457 8.13128L5.8733 15.3037L4.69479 14.1252L11.8672 6.95277L5.54568 6.95277L5.54568 5.28636H14.7121V14.4528L13.0457 14.4528V8.13128Z" fill="#131313"></path></svg></span>'
    cards=''.join(f'''<a data-cognis-expert-card data-dc-tpl="65" href="/blog/{p["slug"]}/" data-h="h2" style="display: flex; flex-direction: column;">
          <div data-dc-tpl="66" style="position: relative; border-radius: 16px; overflow: hidden; aspect-ratio: 3 / 2;">
            <img loading="lazy" decoding="async" data-dc-tpl="67" src="/assets/blog/{p["image"]}" alt="{html.escape(p["title"])}" width="1600" height="900" style="width: 100%; height: 100%; object-fit: cover; display: block;">
            {arrow}
          </div>
          <div data-dc-tpl="71" style="height: 18px;"></div>
          <div data-dc-tpl="72" style="font-size: 14px; color: rgb(123, 123, 123);"><span class="sc-interp">July 26, 2026</span></div>
          <div data-dc-tpl="73" style="height: 12px;"></div>
          <h3 data-dc-tpl="74" style="font-family: &quot;Plus Jakarta Sans&quot;, sans-serif; font-size: 24px; font-weight: 500; letter-spacing: -0.04em; line-height: 1.25; margin: 0px; color: rgb(19, 19, 19);"><span class="sc-interp">{html.escape(p["title"])}</span></h3>
        </a>''' for p in POSTS)
    items=[{"@type":"ListItem","position":i,"url":f'https://cognis.group/blog/{p["slug"]}/',"name":p['title']} for i,p in enumerate(POSTS,1)]
    block=f'''<!-- expert-cards:start -->{cards}<script type="application/ld+json">{json.dumps({"@context":"https://schema.org","@type":"ItemList","name":"Latest Cognis expert articles","itemListElement":items},ensure_ascii=False)}</script><!-- expert-cards:end -->'''
    grid=re.search(r'<div data-dc-tpl="63"[^>]*>',text)
    if not grid: raise RuntimeError('Recent published grid not found')
    text=text[:grid.end()]+block+text[grid.end():]
    path.write_text(text)
    return
    cards=''.join(f'<article class="expert-card"><img src="/assets/blog/{p["image"]}" alt="" loading="lazy" width="800" height="450"><p>{html.escape(p["topic"])}</p><h3><a href="/blog/{p["slug"]}/">{html.escape(p["title"])}</a></h3><div>By <a href="/teams/{p["author_slug"]}/">{html.escape(p["author"])}</a> · {p["reading"]}</div></article>' for p in POSTS)
    items=[{"@type":"ListItem","position":i,"url":f'https://cognis.group/blog/{p["slug"]}/',"name":p['title']} for i,p in enumerate(POSTS,1)]
    block=f'''<!-- expert-posts:start --><style>.expert-cluster{{max-width:1200px;margin:70px auto;padding:0 28px 80px}}.expert-cluster>p{{font-size:12px;font-weight:700;letter-spacing:.13em;text-transform:uppercase}}.expert-cluster>h2{{font:700 clamp(34px,5vw,62px)/1.05 "Plus Jakarta Sans",sans-serif;letter-spacing:-.05em;margin:12px 0 36px}}.expert-grid{{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}}.expert-card{{background:#fff;border-radius:18px;overflow:hidden;padding:0 28px 28px;min-height:400px;display:flex;flex-direction:column}}.expert-card img{{width:calc(100% + 56px);height:210px;margin:0 -28px 20px;object-fit:cover}}.expert-card p{{font:700 11px/1.3 Inter,sans-serif;text-transform:uppercase;letter-spacing:.12em;color:#666}}.expert-card h3{{font:650 25px/1.17 "Plus Jakarta Sans",sans-serif;letter-spacing:-.035em;margin:10px 0 24px}}.expert-card h3 a,.expert-card div a{{text-decoration:none}}.expert-card div{{margin-top:auto;font:500 13px/1.4 Inter,sans-serif;color:#666}}@media(max-width:720px){{.expert-grid{{grid-template-columns:1fr}}}}</style><section class="expert-cluster" aria-labelledby="expert-title"><p>New expert field notes</p><h2 id="expert-title">Security, governance, and agent products</h2><div class="expert-grid">{cards}</div></section><script type="application/ld+json">{json.dumps({"@context":"https://schema.org","@type":"ItemList","name":"Cognis expert field notes","itemListElement":items},ensure_ascii=False)}</script><!-- expert-posts:end -->'''
    block=block.replace('</style>', '.expert-cluster>h2,.expert-card h3,.expert-card h3 a{color:#131313!important;opacity:1!important}</style>', 1)
    pos=text.find('<footer');
    if pos<0: raise RuntimeError('blog footer not found')
    path.write_text(text[:pos]+block+text[pos:])

def update_author_profiles():
    for author_slug in ('kola-olatunde', 'tosin-salami'):
        path=ROOT/'teams'/author_slug/'index.html'; text=path.read_text(); text=re.sub(r'<!-- authored-insights:start -->.*?<!-- authored-insights:end -->','',text,flags=re.S)
        authored=[p for p in POSTS if p['author_slug']==author_slug]
        cards=''.join(f'<li><a href="/blog/{p["slug"]}/">{html.escape(p["title"])}</a><span>{html.escape(p["topic"])}</span></li>' for p in authored)
        block=f'''<!-- authored-insights:start --><style>.authored-insights{{max-width:1080px;margin:0 auto 76px;padding:36px max(20px,5vw);background:#f2f2f2;border-radius:22px}}.authored-insights h2{{font:700 clamp(28px,4vw,44px)/1.1 "Plus Jakarta Sans",sans-serif;letter-spacing:-.04em;margin:0 0 24px}}.authored-insights ul{{list-style:none;margin:0;padding:0}}.authored-insights li{{display:flex;justify-content:space-between;gap:24px;padding:17px 0;border-top:1px solid #d8d8d8}}.authored-insights a{{font:650 17px/1.4 "Plus Jakarta Sans",sans-serif;text-decoration:none}}.authored-insights span{{font:600 11px/1.4 Inter,sans-serif;text-transform:uppercase;letter-spacing:.1em;color:#666}}@media(max-width:650px){{.authored-insights{{margin-left:12px;margin-right:12px}}.authored-insights li{{display:block}}.authored-insights span{{display:block;margin-top:6px}}}}</style><section class="authored-insights" aria-labelledby="authored-{author_slug}"><h2 id="authored-{author_slug}">Field notes by {html.escape(authored[0]['author'])}</h2><ul>{cards}</ul></section><!-- authored-insights:end -->'''
        block=block.replace('</style>', '.authored-insights h2{color:#131313!important;opacity:1!important}</style>', 1)
        pos=text.find('<footer')
        if pos<0: raise RuntimeError(f'profile footer not found: {author_slug}')
        path.write_text(text[:pos]+block+text[pos:])

def main():
    for p in POSTS:
        if p['slug'] == 'ai-governance-africa-2026':
            p.update(alt='A leadership team in a focused strategy session, representing accountable AI governance', credit='Memento Media', source='https://unsplash.com/photos/2pPw5Glro5I')
        out=ROOT/'blog'/p['slug']/'index.html'; out.parent.mkdir(parents=True,exist_ok=True)
        page=render(p).replace(f"<title>{html.escape(p['title'])} | Cognis Group</title>", f"<title>{html.escape(SEO_TITLES.get(p['slug'], p['title']+' | Cognis Group'))}</title>")
        page=aligned_post_page(page,p)
        out.write_text(page); print('  wrote',out.relative_to(ROOT))
    update_hub(); update_author_profiles(); print('  updated blog hub and author profiles')
if __name__=='__main__': main()
